    @BeforeAll static void database(){String url=System.getenv("MP_DB_URL");if(url==null||!url.startsWith("jdbc:mysql://127.0.0.1:13306/majorpilot?"))throw new IllegalStateException("Dedicated test database required");var source=new DriverManagerDataSource(url.replace("/majorpilot?","/majorpilot_test?"),System.getenv("MP_DB_USERNAME"),System.getenv("MP_DB_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").cleanDisabled(true).load().migrate();db=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));mapper=new ObjectMapper().findAndRegisterModules();repository=new TaskContentRepository(mapper);publication=new TaskPublicationService(db,tx,repository,mapper,true);publication.installTechnicalDemos();content=new PublishedTaskContentProvider(db,repository,true);}
