    static String key(){return UUID.randomUUID().toString();}JsonNode json(String text){try{return mapper.readTree(text);}catch(Exception e){throw new IllegalStateException(e);}}
    RunDtos.Run create(String demo){return runs.create(student,key(),new RunDtos.Create(null,demo,null));}
    RunDtos.Run start(RunDtos.Run run){return runs.transition(student,run.runId(),"start",key(),new RunDtos.Transition(run.revision(),null,null));}
