    @Test void createStartSwitchPauseAndResumeAreAtomicAndPreserveProgress(){var a=create("DEMO_TABLE");assertNull(a.taskVersionId());assertEquals("READY",a.status());assertEquals(a.runId(),create("DEMO_TABLE").runId());a=start(a);String pinned=a.taskVersionId();save(a,"prepare","{\"acknowledged\":true}");a=current(a);var b=create("DEMO_COMPARE");final var target=b;error("ACTIVE_RUN_EXISTS",()->start(target));final var active=a;error("RUN_REVISION_CONFLICT",()->runs.transition(student,target.runId(),"start",key(),new RunDtos.Transition(target.revision(),active.runId(),0L)));assertEquals("IN_PROGRESS",current(a).status());assertEquals("READY",current(b).status());
        b=runs.transition(student,b.runId(),"start",key(),new RunDtos.Transition(b.revision(),a.runId(),a.revision()));assertEquals("PAUSED",current(a).status());final String aId=a.runId();error("RUN_PAUSED",()->runs.save(student,aId,"prepare",new RunDtos.Save(1L,"demo-response-v1",json("{}"))));a=current(a);a=runs.transition(student,a.runId(),"resume",key(),new RunDtos.Transition(a.revision(),b.runId(),b.revision()));assertEquals(pinned,a.taskVersionId());assertEquals(1,runs.step(student,a.runId(),"prepare").revision());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_experience_run WHERE student_id=? AND active_guard=1",Integer.class,student.internalId()));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_experience_run WHERE student_id=? AND content_kind='MAJOR'",Integer.class,student.internalId()));}
