    @Test void disabledDemoCannotBeReadThroughPreviouslyCompletedIdempotencyResults(){
        String createKey=key(),startKey=key(),completeKey=key();var createInput=new RunDtos.Create(null,"DEMO_TABLE",null);
        var ready=runs.create(student,createKey,createInput);var startInput=new RunDtos.Transition(ready.revision(),null,null);
        var active=runs.transition(student,ready.runId(),"start",startKey,startInput);var saved=save(active,"prepare","{\"acknowledged\":true}");var completionInput=new RunDtos.Revision(saved.revision());
        runs.completeStep(student,active.runId(),"prepare",completeKey,completionInput);
        var disabled=new RunService(new RunStore(db,mapper,false),mock(TaskContentProvider.class),idem,tx);
        error("RESOURCE_NOT_FOUND",()->disabled.create(student,createKey,createInput));
        error("RESOURCE_NOT_FOUND",()->disabled.transition(student,ready.runId(),"start",startKey,startInput));
        error("RESOURCE_NOT_FOUND",()->disabled.completeStep(student,active.runId(),"prepare",completeKey,completionInput));
        // Normal lifecycle changes still permit authenticated replays when the feature remains enabled.
        assertEquals(active,runs.transition(student,ready.runId(),"start",startKey,startInput));
        String recoveryKey=key();var recoveryInput=new RunDtos.Recovery(current(active).revision(),"TECHNICAL_FAILURE","Synthetic replay feature boundary");
        var recovered=runs.recover(1,active.runId(),recoveryKey,recoveryInput,"synthetic-feature-boundary");
        assertEquals(recovered,runs.recover(1,active.runId(),recoveryKey,recoveryInput,"synthetic-feature-boundary"));
        error("RESOURCE_NOT_FOUND",()->disabled.recover(1,active.runId(),recoveryKey,recoveryInput,"synthetic-feature-boundary"));
    }
