    @Test void reopeningCompletedStepInvalidatesTransitiveDependentsButPreservesHistory(){
        var run=toExecution();var saved=save(run,"adjust","{\"multiplier\":1,\"include\":\"ALL\"}");executions.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",saved.revision(),json("{}"),null,null));
        runs.completeStep(student,run.runId(),"adjust",key(),new RunDtos.Revision(saved.revision()));complete(run,"observe","{\"observation\":\"我先记录了原始数据的总和与均值，然后准备修改倍数继续验证。\"}");
        var changed=save(run,"adjust","{\"multiplier\":2,\"include\":\"ALL\"}");assertEquals(List.of("adjust","observe","submit"),changed.invalidatedStepKeys());
        var state=current(run);assertEquals("IN_PROGRESS",state.steps().stream().filter(s->s.stepKey().equals("observe")).findFirst().orElseThrow().status());
        error("STEP_NOT_AVAILABLE",()->runs.step(student,run.runId(),"observe"));
        error("STEP_REVISION_CONFLICT",()->runs.save(student,run.runId(),"adjust",new RunDtos.Save(1L,"demo-response-v1",json("{}"))));
        error("EXECUTION_NOT_ALLOWED",()->runs.completeStep(student,run.runId(),"adjust",key(),new RunDtos.Revision(changed.revision())));
        assertEquals(4,db.queryForObject("SELECT COUNT(*) FROM mp_step_completion c JOIN mp_step_state s ON s.id=c.step_state_id JOIN mp_experience_run r ON r.id=s.experience_run_id WHERE r.student_id=?",Integer.class,student.internalId()));
        executions.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",changed.revision(),json("{}"),null,null));runs.completeStep(student,run.runId(),"adjust",key(),new RunDtos.Revision(changed.revision()));
        assertTrue(runs.step(student,run.runId(),"observe").response().has("observation"));assertEquals(5,db.queryForObject("SELECT COUNT(*) FROM mp_step_completion c JOIN mp_step_state s ON s.id=c.step_state_id JOIN mp_experience_run r ON r.id=s.experience_run_id WHERE r.student_id=?",Integer.class,student.internalId()));
    }
    @Test void optionalFollowUpHasOneSuccessAndNeverMakesCoreReflectionRequired(){
        var run=toReflection();var calls=new java.util.concurrent.atomic.AtomicInteger();HintProvider provider=new HintProvider(){public Result hint(Context ignored){throw new UnsupportedOperationException();}public Result followUp(Context context){assertFalse(TransactionSynchronizationManager.isActualTransactionActive());calls.incrementAndGet();return new Result(mapper.createObjectNode().put("question","哪一步让你想继续探索？"),"SYNTHETIC",null,"fixture-v1","SUCCEEDED");}};
        var service=new FollowUpService(reflections,provider,mock(RateLimits.class));var input=new RunDtos.Revision(0L);String request=key();assertEquals("SUCCEEDED",service.request(student,run.runId(),request,input).status());assertEquals("SUCCEEDED",service.request(student,run.runId(),key(),input).status());assertEquals(1,calls.get());
        var reflected=reflections.get(student,run.runId());assertFalse(reflected.followUp().has("claim"));assertFalse(reflected.followUp().has("requestId"));
        var closed=reflections.submit(student,run.runId(),key(),new RunDtos.ReflectionSave(0L,"demo-reflection-v1",json("{\"interestingStepKeys\":[\"NONE\"],\"difficultySources\":[\"NONE\"],\"continueSimilarWork\":\"NO\"}")));assertEquals("CLOSED",closed.status());
    }
    @Test void successfulConfigurationQuotaIsDurableAndReuseDoesNotChargeAgain(){
        // A synthetic content port fixes a one-success quota; no published content is altered.
        TaskContentProvider policy=new TaskContentProvider(){
            TaskContent.Version limited(TaskContent.Version v){var manifest=v.manifest();((com.fasterxml.jackson.databind.node.ObjectNode)manifest.path("operations").get(0)).put("maxEvaluations",1);return new TaskContent.Version(v.internalId(),v.taskVersionId(),v.contentKind(),v.majorCode(),v.demoKey(),v.versionCode(),v.manifestSha256(),manifest);}
            public TaskContent.Version currentMajor(String code){return limited(content.currentMajor(code));}public TaskContent.Version currentDemo(String key){return limited(content.currentDemo(key));}public TaskContent.Version pinned(String id){return limited(content.pinned(id));}public TaskContent.Asset publicAsset(TaskContent.Version version,String key){return content.publicAsset(version,key);}
        };
        var run=toExecution();var service=new ExecutionService(new RunService(store,policy,idem,tx),new FixedExecutionCalculator(content,mapper),mock(RateLimits.class));
        var first=save(run,"adjust","{\"multiplier\":1,\"include\":\"ALL\"}");var result=service.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",first.revision(),json("{}"),null,null));assertEquals(0,result.remainingEvaluations());
        var second=save(run,"adjust","{\"multiplier\":2,\"include\":\"ALL\"}");error("EVALUATION_LIMIT_REACHED",()->service.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",second.revision(),json("{}"),null,null)));
        var third=save(run,"adjust","{\"multiplier\":1,\"include\":\"ALL\"}");var reloaded=new ExecutionService(new RunService(new RunStore(db,mapper,true),policy,idem,tx),new FixedExecutionCalculator(content,mapper),mock(RateLimits.class));
        var reused=reloaded.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",third.revision(),json("{}"),null,null));assertTrue(reused.reused());assertEquals(result.executionId(),reused.executionId());assertEquals(0,reused.remainingEvaluations());
    }
    @Test void reusedExecutionPreservesOriginalRevisionAndExposesCurrentBindingAfterReload(){
        var run=toExecution();var first=save(run,"adjust","{\"multiplier\":1,\"include\":\"ALL\"}");
        var original=executions.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",first.revision(),json("{}"),null,null));
        save(run,"adjust","{\"multiplier\":2,\"include\":\"ALL\"}");assertNull(runs.step(student,run.runId(),"adjust").executions().getFirst().appliedToRevision());
        var current=save(run,"adjust","{\"multiplier\":1,\"include\":\"ALL\"}");
        var reused=executions.execute(student,run.runId(),key(),new RunDtos.Execute("demo-summary-v1",current.revision(),json("{}"),null,null));
        assertEquals(original.inputRevision(),reused.inputRevision());assertEquals(current.revision(),reused.appliedToRevision());
        var reloaded=runs.step(student,run.runId(),"adjust").executions().getFirst();assertEquals(original.executionId(),reloaded.executionId());assertEquals(current.revision(),reloaded.appliedToRevision());assertTrue(reloaded.remainingEvaluations()>=0);
    }
